@props(['project','task'=>null])<form action="/projects/{{ $project->id }}/tasks/{{ $task?->id }}" method="post" class="stack">@csrf<div class="row between"><h2>{{ $task ? 'Edit task':'Plan the next step.' }}</h2><button type="button" data-close class="icon-button">×</button></div><label>Task title<input name="title" value="{{ $task?->title }}" required maxlength="200"></label><div class="form-grid"><label>Status<select name="status">@foreach(['todo'=>'To do','in_progress'=>'In progress','in_review'=>'In review','blocked'=>'Blocked','done'=>'Done'] as $key=>$label)<option value="{{ $key }}" @selected($task?->status===$key)>{{ $label }}</option>@endforeach</select></label><label>Priority<select name="priority">@foreach(['low','medium','high'] as $priority)<option @selected(($task?->priority??'medium')===$priority)>{{ $priority }}</option>@endforeach</select></label></div><label>Assignee<select name="assignee_id"><option value="">Unassigned</option>@foreach($project->members->where('active',true) as $u)<option value="{{ $u->id }}" @selected($task?->assignee_id===$u->id)>{{ $u->name }}</option>@endforeach</select></label><div class="form-grid"><label>Start date<input name="start_date" type="date" value="{{ $task?->start_date }}"></label><label>Due date<input name="due_date" type="date" value="{{ $task?->due_date }}"></label></div><label class="inline"><input type="checkbox" name="milestone" value="1" @checked($task?->milestone)> This is a milestone</label><button class="button">Save task</button></form>
